                                    const char *p, const char *q,
                                    fmt_aux_t *fmt) {
     kstring_t *mem = (kstring_t*)&h->mem;

     int j;
     for (j = 0; j < v->n_fmt; ++j) {
         fmt_aux_t *f = &fmt[j];
         if ( !f->max_m ) f->max_m = 1;  // omitted trailing format field

