   614      hts_pos_t l;
   615      for (k = l = 0; k < n_cigar; ++k)
   616          if (bam_cigar_type(bam_cigar_op(cigar[k]))&1)
   617              l += bam_cigar_oplen(cigar[k]);
   618      return l;
   619  }
