   621  hts_pos_t bam_cigar2rlen(int n_cigar, const uint32_t *cigar)
   622  {
   623      int k;
   624      hts_pos_t l;
   625      for (k = l = 0; k < n_cigar; ++k)
   626          if (bam_cigar_type(bam_cigar_op(cigar[k]))&2)
   627              l += bam_cigar_oplen(cigar[k]);
