  3921  int bam_aux_append(bam1_t *b, const char tag[2], char type, int len, const uint8_t *data)
  3922  {
  3923      uint32_t new_len;
  3924
  3925      assert(b->l_data >= 0);
  3926      new_len = b->l_data + 3 + len;
  3927      if (new_len > INT32_MAX || new_len < b->l_data) goto nomem;
  3928
  3929      if (realloc_bam_data(b, new_len) < 0) return -1;
  3930
  3931      b->data[b->l_data] = tag[0];
  3932      b->data[b->l_data + 1] = tag[1];
  3933      b->data[b->l_data + 2] = type;
  3934
  3935  #ifdef HTS_LITTLE_ENDIAN
