  3979  uint8_t *bam_aux_get(const bam1_t *b, const char tag[2])
  3980  {
  3981      uint8_t *s, *end, *t = (uint8_t *) tag;
  3982      uint16_t y = (uint16_t) t[0]<<8 | t[1];
  3983      s = bam_get_aux(b);
  3984      end = b->data + b->l_data;
  3985      while (s != NULL && end - s >= 3) {
  3986          uint16_t x = (uint16_t) s[0]<<8 | s[1];
  3987          s += 2;
  3988          if (x == y) {
  3989              // Check the tag value is valid and complete
  3990              uint8_t *e = skip_aux(s, end);
  3991              if ((*s == 'Z' || *s == 'H') && *(e - 1) != '\0') {
  3992                  goto bad_aux;  // Unterminated string
  3993              }
  3994              if (e != NULL) {
  3995                  return s;
  3996              } else {
  3997                  goto bad_aux;
  3998              }
  3999          }
  4000          s = skip_aux(s, end);
  4001      }
  4002      if (s == NULL) goto bad_aux;
  4003      errno = ENOENT;
  4004      return NULL;
